create or replace view store.compliance_findings as
select 'EVIDENCE_REVIEW' rule,e.code reference,s.name site,'Review purpose, access and retention for this evidence' finding from store.evidence e join store.checks c on c.id=e.check_id join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where e.review_on<current_date
union all select 'FAILURE_WITHOUT_ACTION',a.code||'/'||c.code,s.name,'Failed check has no corrective action' from store.checks c join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where c.outcome='fail' and not exists(select 1 from store.actions x where x.check_id=c.id)
union all select 'UNANSWERED_IMPORT',a.code||'/'||c.code,s.name,'Source answer needs mapping review' from store.checks c join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where a.status='imported' and c.outcome is null
union all select 'OVERDUE_ACTION',x.code,s.name,'Corrective action is past due and not verified' from store.actions x join store.checks c on c.id=x.check_id join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where x.state<>'verified' and x.due_date<current_date
union all select 'PRICE_DISPLAY_REVIEW',a.code||'/'||c.code,s.name,'Recorded shelf/checkout discrepancy needs consumer-pricing review' from store.checks c join store.audits a on a.id=c.audit_id join store.sites s on s.id=a.site_id where c.code='PRICE' and c.outcome='fail' and s.country in ('NZ','AU') and not exists(select 1 from store.actions x where x.check_id=c.id and x.state='verified');
